import narwhals as nw
import pandas as pd
import polars as pl


@nw.narwhalify
def add_total(df):
    return df.with_columns(
        total=(nw.col("price") * nw.col("quantity")).alias("total")
    )


if __name__ == "__main__":
    # Test with pandas
    pandas_df = pd.DataFrame({
        "price": [10.0, 20.0, 30.0],
        "quantity": [2, 3, 4]
    })
    print("Pandas input:")
    print(pandas_df)
    print("\nPandas output:")
    print(add_total(pandas_df))

    # Test with polars
    polars_df = pl.DataFrame({
        "price": [10.0, 20.0, 30.0],
        "quantity": [2, 3, 4]
    })
    print("\nPolars input:")
    print(polars_df)
    print("\nPolars output:")
    print(add_total(polars_df))
